const rawProfile = pm.collectionVariables.get("profileData");
if (!rawProfile) {
  throw new Error("profileData is empty: run the GET request first.");
}

const profile = JSON.parse(rawProfile);   // deep copy, so everything else stays untouched

const dyn = (n) => pm.variables.replaceIn(`{{$${n}}}`);
const slugify = (s) => s.toLowerCase()
  .normalize("NFD").replace(/[\u0300-\u036f]/g, "")
  .replace(/[^a-z]+/g, "-").replace(/^-|-$/g, "");

// ---- minor edits: header fields only ----
const first = dyn("randomFirstName");
const last = dyn("randomLastName");
const slug = slugify(`${first} ${last}`);

profile.name = `${first} ${last}`;
pm.variables.set("name",profile.name);

profile.email = `${slug.replace(/-/g, ".")}@example.com`;
profile.phone = dyn("randomPhoneNumber");

profile.location = `${dyn("randomCity")}, ${dyn("randomCountry")}`;
profile.linkedin = `https://www.linkedin.com/in/${slug}-user/`;

// Everything else (summary, skills, experiences, education,
// certifications, languages, etc.) is left exactly as returned by the GET.
let payload = {
    data : profile,
    output_language : "English",
}

pm.variables.set("payload", JSON.stringify(payload));

pm.test('creates the matching prerequisite job', () => {
  pm.response.to.have.status(202);
  const body = pm.response.json();
  pm.expect(body.id).to.not.be.null;
  pm.expect(body).to.have.property("title");
  pm.expect(body).to.have.property("status");
  pm.expect(body.status).to.eql('processing');
  pm.collectionVariables.unset('job_normalization_poll_tries');
  pm.collectionVariables.set('job_id', body.id);
  pm.collectionVariables.set('job_processing_job_id', body.processing_job_id);
});

const rnd = (a, b) => Math.floor(Math.random() * (b - a + 1)) + a;
const digits = (n) => Array.from({ length: n }, () => rnd(0, 9)).join("");
const hex = (n) => Array.from({ length: n }, () => rnd(0, 15).toString(16)).join("");

// One generator per source, using each site's real URL shape
const urlGenerators = {
  jobBank:  () => `https://www.jobbank.gc.ca/jobsearch/jobposting/${digits(8)}`,
  indeed:   () => `https://ca.indeed.com/viewjob?jk=${hex(16)}`,
  linkedin: () => `https://www.linkedin.com/jobs/view/${digits(10)}`
};

// Optional: force a source with a variable "jobSource" (jobBank | indeed | linkedin)
const sources = Object.keys(urlGenerators);
const forced = pm.variables.get("jobSource");
const source = sources.includes(forced) ? forced : sources[rnd(0, sources.length - 1)];

// Content: Runner data file (column "content") first, else the collection variable
const content =
  (pm.iterationData && pm.iterationData.get("content")) ||
  pm.collectionVariables.get("jobPostingContent");

if (!content) {
  throw new Error("No content: set the collection variable 'jobPostingContent' or use a data file with a 'content' column.");
}

const payload = { url: urlGenerators[source](), content };

pm.variables.set("payload", JSON.stringify(payload));
pm.variables.set("generatedSource", source);

const body = pm.response.json();
pm.test('returns the first page of normalized job headers', () => {
  pm.response.to.have.status(200);
  pm.expect(body).to.have.all.keys('items', 'total', 'page', 'limit');
  pm.expect(body.page).to.eql(1);
  pm.expect(body.limit).to.eql(20);
  pm.expect(body.items).to.be.an('array').and.have.length.at.most(20);
  pm.expect(body.total).to.be.a('number').and.at.least(body.items.length);
});
pm.test('returns only header fields, newest posting dates first, and the setup job', () => {
  const headerFields = ['id', 'title', 'company', 'location', 'postingDate', 'source'];
  body.items.forEach(item => pm.expect(item).to.have.all.keys(...headerFields));
  const validDates = body.items
    .map(item => Date.parse(item.postingDate))
    .filter(timestamp => Number.isFinite(timestamp));
  pm.expect(validDates).to.eql([...validDates].sort((left, right) => right - left));
  pm.expect(body.items.map(item => item.id)).to.include(pm.collectionVariables.get('job_id'));
});

